SELECT CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, AVG(discount) AS avg_discount, COUNT(CASE WHEN status = 'SHIPPED' THEN 1 END) AS shipped_count, SUM(CASE WHEN status = 'SHIPPED' THEN discount ELSE 0 END) AS shipped_discount FROM orders GROUP BY CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING SUM(CASE WHEN status = 'SHIPPED' THEN discount ELSE 0 END) >= 29;
